import pytest
import asyncio
from browser_use.browser.watchdogs.security_watchdog import SecurityWatchdog

class DummyEvent:
    def __init__(self, url):
        self.url = url
        self.target_id = 'dummy-target'

class DummyBus:
    def __init__(self):
        self.dispatched = []
    def dispatch(self, event):
        self.dispatched.append(event)

@pytest.mark.asyncio
async def test_blocked_counter_incremented():
    watchdog = SecurityWatchdog()
    # Attach minimal logger and dummy event bus
    watchdog.logger = logging.getLogger('test_security_watchdog')
    watchdog.event_bus = DummyBus()

    # Use a URL that is not in the internal allowlist (should be blocked)
    event = DummyEvent('http://example.com/')

    with pytest.raises(ValueError):
        await watchdog.on_NavigateToUrlEvent(event)

    assert watchdog.blocked_count == 1
